UPDATE sys_category
category_name = #{categoryName}, parent_id = #{parentId}, sort_order = #{sortOrder}, icon = #{icon}, status = #{status},
WHERE id = #{id}

mapper.select:
WITH RECURSIVE category_descendants AS (
    SELECT id FROM sys_category WHERE id = #{id}
    UNION ALL
    SELECT c.id
    FROM sys_category c
    INNER JOIN category_descendants d ON c.parent_id = d.id
)
SELECT id FROM category_descendants WHERE id <> #{id}

